// The audit log's signing key (docs/features/audit-chain.md, D81). The key is an Ed25519 private
// key in .env (AUDIT_SIGNING_KEY, base64 PKCS#8), generated by `npm run db:setup` and never
// stored in the database or the repository. Someone with database access but not the key can
// still edit rows, but cannot sign the hashes the edit needs, so the verifier sees it.
//
// Ed25519 rather than HMAC: verifying needs only the public key, which the audit page shows, so
// whoever checks the log cannot also forge it.
import { createPrivateKey, createPublicKey, sign, verify, type KeyObject } from 'node:crypto';
import type { SignatureCheck } from '@/domain/audit';

export const SIGNING_KEY_ENV = 'AUDIT_SIGNING_KEY';

/** The environment, or a stand-in for it in tests. */
type Env = Readonly<Record<string, string | undefined>>;

export type AuditSigner = {
  /** Base64 Ed25519 signature of `message` (UTF-8). */
  sign(message: string): string;
  check: SignatureCheck;
  /** Base64 SPKI DER of the public key: the one thing a verifier needs. */
  publicKey: string;
};

/** A signer for a base64 PKCS#8 Ed25519 key. Throws, naming the variable but not the key. */
export function signerFromKey(base64Key: string): AuditSigner {
  let privateKey: KeyObject;
  try {
    privateKey = createPrivateKey({
      key: Buffer.from(base64Key, 'base64'),
      format: 'der',
      type: 'pkcs8',
    });
  } catch {
    throw new Error(`${SIGNING_KEY_ENV} is not a base64 PKCS#8 key; run \`npm run db:setup\`.`);
  }
  if (privateKey.asymmetricKeyType !== 'ed25519') {
    throw new Error(`${SIGNING_KEY_ENV} is not an Ed25519 key; run \`npm run db:setup\`.`);
  }
  const publicKey = createPublicKey(privateKey);
  return {
    // Ed25519 takes no digest name: the algorithm argument is null.
    sign: (message) => sign(null, Buffer.from(message, 'utf8'), privateKey).toString('base64'),
    check: (message, signature) => {
      try {
        return verify(
          null,
          Buffer.from(message, 'utf8'),
          publicKey,
          Buffer.from(signature, 'base64')
        );
      } catch {
        return false;
      }
    },
    publicKey: publicKey.export({ format: 'der', type: 'spki' }).toString('base64'),
  };
}

let cached: { key: string; signer: AuditSigner } | null = null;

/** The signer for the key in `env`, parsed once per key; null when no key is set. */
export function auditSigner(env: Env = process.env): AuditSigner | null {
  const key = env[SIGNING_KEY_ENV]?.trim();
  if (!key) return null;
  if (cached?.key !== key) cached = { key, signer: signerFromKey(key) };
  return cached.signer;
}
